int runOriginalStateCorpus(const std::string& folder,const std::string& disc){using namespace Snatcher;std::string error;unsigned accepted=0,unsupported=0,requests=0;unsigned kinds[kRequestGameSave+1]={0};
 for(unsigned index=0;index<39;++index){char filename[32];std::snprintf(filename,sizeof(filename),"/SP%02u.BIN",index);std::ifstream file((folder+filename).c_str(),std::ios::binary);std::vector<uint8_t> bytes((std::istreambuf_iterator<char>(file)),std::istreambuf_iterator<char>());std::vector<Scenario> scenarios(39);if(!file&&!file.eof())return 2;if(!parseScenario(bytes.data(),bytes.size(),scenarios[index],error))return 2;
  EventScheduler beforeEvents,afterEvents;SemanticTrace beforeTrace,afterTrace;NarrativeRuntime before(scenarios,beforeEvents,beforeTrace),after(scenarios,afterEvents,afterTrace);
  for(const Node& node:scenarios[index].nodes){switch(node.opcode){case 0:case 4:case 5:case 0x0a:case 0x0d:case 0x0f:case 0x3d:case 0x41:case 0x42:case 0x43:case 0x44:case 0x45:case 0x46:case 0x47:case 0x48:case 0x49:case 0x4a:break;default:continue;}
   if(!before.start(Cursor(uint16_t(57+index),node.offset),std::vector<uint8_t>(352,0),error))return 3;RuntimeStatus status=before.run();if(status==kRuntimeUnsupported){++unsupported;continue;}if(status!=kRuntimeWaiting&&status!=kRuntimePassFinished){std::fprintf(stderr,"unexpected corpus status %u:%u: %s\n",57+index,node.offset,before.diagnostic().c_str());return 4;}
   NarrativeSnapshot captured,decoded;NativeSaveSection section;std::vector<EventRebind> rebind;
   if(!before.snapshot(disc,captured,error)||!encodeNarrativeState(captured,section,error)||!decodeNarrativeState(section,disc,decoded,error)||!after.restore(decoded,disc,beforeEvents.snapshot(),rebind,error)){std::fprintf(stderr,"snapshot corpus failure %u:%u: %s\n",57+index,node.offset,error.c_str());return 5;}
   if(after.status()!=before.status()||after.packed()!=before.packed()||after.requests().size()!=before.requests().size()||after.lastPresentation()!=before.lastPresentation())return 6;
   for(size_t i=0;i<before.requests().size();++i){const RuntimeRequest& a=before.requests()[i];const RuntimeRequest& b=after.requests()[i];if(a.kind!=b.kind||!(a.owner==b.owner)||a.first!=b.first||a.second!=b.second||a.queue!=b.queue||a.operands!=b.operands||a.token==b.token||!afterEvents.awaiting(b.token))return 7;++kinds[a.kind];++requests;}
   ++accepted;
  }
 }
 std::printf("{\"status\":\"PASS\",\"producer_snapshots_exact\":%u,\"pending_requests_exact\":%u,\"unsupported_producer_contexts\":%u,\"request_kind_counts\":[",accepted,requests,unsupported);for(unsigned i=0;i<=kRequestGameSave;++i)std::printf("%s%u",i?",":"",kinds[i]);std::printf("]}\n");return 0;
}
int main(int argc,char** argv){try{if(argc==4&&std::string(argv[1])=="--original")return runOriginalStateCorpus(argv[2],argv[3]);if(argc!=1)return 2;return runNarrativeStateTests();}catch(const std::exception& error){std::fprintf(stderr,"narrative state test failure: %s\n",error.what());return 1;}}
